I think we talked about this in the past, and this is technically an issue for posix/windows, as this flag is `blocking`. While you're here, would you mind updating this? I think we could drop something lile:
```
  auto blocking = isPlatform(PlatformType::TYPE_WINDOWS) ? true : false;
  auto s = readFile(path,
                    0,
                    kHashChunkSize,
                    false,
                    true,
                    ([&hashes, &mask](std::string& buffer, size_t size) {
                      for (auto& hash : hashes) {
                        if (mask & hash.first) {
                          hash.second->update(&buffer[0], size);
                        }
                      }
                    }),
                    blocking);

```
